<template><div class="app-container"><el-table v-loading="loading" :data="rows"><el-table-column prop="couponName" label="优惠券"/><el-table-column label="门槛" width="120"><template #default="s">¥{{(s.row.thresholdAmount/100).toFixed(2)}}</template></el-table-column><el-table-column label="优惠" width="120"><template #default="s">¥{{(s.row.discountAmount/100).toFixed(2)}}</template></el-table-column><el-table-column prop="totalQuantity" label="总量"/><el-table-column prop="receivedQuantity" label="已领"/><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="toggle(s.row)">{{s.row.status==='0'?'停用':'启用'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div></template><script setup name="ShopCoupon">import{ref,getCurrentInstance}from'vue';import{changeCouponStatus,deleteCoupon,listCoupon}from'@/api/shop/coupon';const{proxy}=getCurrentInstance(),loading=ref(false),rows=ref([]);function load(){loading.value=true;listCoupon().then(r=>rows.value=r.rows).finally(()=>loading.value=false)}function toggle(r){changeCouponStatus(r.couponId,r.status==='0'?'1':'0').then(load)}function remove(r){proxy.$modal.confirm(`确认删除“${r.couponName}”？`).then(()=>deleteCoupon(r.couponId)).then(load).catch(()=>{})}load()</script>
